class GenericRuOperations(GenericBts):
    """RU(Radio Unit) keywords for eNB and gNB"""

    @load_moler_configuration_from_tl()
    def get_ru_device(self, bts_id=0, du_id=0, ru_id=0, device_name=None, serial_number=None):
        """
        Get RU moler device object.
        :param bts_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param ru_id:       ID of radio unit. Default: 1
        :param device_name: RU device name. Default: None
        :param serial_number: RU serial number. Default: None
        :return:           RU device object
        """
        if device_name is None:
            device_name = self.ssh_ru_alias.format(bts_id, du_id, ru_id)
        ru = DeviceFactory.get_device(name=device_name, establish_connection=False)
        if serial_number is not None:
            ru.serial_number = serial_number
        ru.goto_state('RU')
        return ru

    def check_ru_ip_addresses_collected_by_webem_vs_collected_by_moler(self, bts_id=0, du_id=0, ru_id=0):
        """
        Compare RU IP addresses collected by WebEM vs collected by Moler
        :param bts_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param ru_id:       ID of radio unit. Default: 1
        :return:
        """
        ru = self.get_ru_device(bts_id=bts_id, du_id=du_id, ru_id=ru_id)
        webem_ip_addresses = self.get_rmod_ip_address(serial_number=ru.serial_number, bts_id=bts_id, du_id=du_id)
        moler_ip_addresses = ru.ru_ip_address
        if webem_ip_addresses != moler_ip_addresses:
            logging.debug(f"IP address detected by moler: {moler_ip_addresses}")
            logging.debug(f"IP address detected by WebEM: {webem_ip_addresses}")
            logging.warning("RU IP addresses collected by WebEM and Moler are NOT equal")
            return False
        logging.info(f"RU IP addresses collected by WebEM and Moler are equal - {moler_ip_addresses}")
        return True

    def check_ru_ip_addresses_collected_by_webem_vs_collected_by_moler_for_all_rus(self, bts_id=0, du_id=0):
        """
        Compare RU IP addresses collected by WebEM vs collected by Moler for all RUs
        :param bts_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:
        """
        ip_statuses = []
        all_rus = tl_config.get_count_of_radios()
        for ru_id in range(all_rus):
            status = self.check_ru_ip_addresses_collected_by_webem_vs_collected_by_moler(bts_id=bts_id,
                                                                                         du_id=du_id, ru_id=ru_id)
            ip_statuses.append(status)

        return all(ip_statuses)

    @login_logout
    def get_rmod_ip_address(self, serial_number, bts_id=0, du_id=0):
        results = self.admin.get_managed_objects(connection=self.rest_alias.format(bts_id, du_id),
                                                 class_name='RMOD_L')
        for radio_object in results:
            params = radio_object['parameters']
            if params['serialNumber'] == serial_number:
                logging.info(f"RU IP address for {serial_number}: {params['ipAddress']}")
                return params['ipAddress']

    def get_radio_unit_configuration_based_on_tl_config_id(self, ru_id, bts_id=0, du_id=0):
        """
        Get Radio Unit configuration by its id from Testline Configuration

        :param ru_id:      Radio Unit id - related to Test Line configuration
        :param bts_id:     ID of gNB/eNB, default 0
        :param du_id:      DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: dict: Radio Unit configuration, e.g.:
                {
                    'configuration_dist_name': 'MRBTS-75205/EQM-1/APEQM-1/RMOD-2',
                    'configuration_id': '2',
                    'configuration_object': 'RMOD-2',
                    'runtime_dist_name': '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-2'
                }
        """
        tl_config_serial_number = tl_config.get_radio_serial_number(bts_id=bts_id, du_id=du_id, ru_id=ru_id)
        rus_info = self._get_all_rus_info()
        for ru_info in rus_info:
            if tl_config_serial_number == ru_info['serialNumber']:
                configuration_dist_name = ru_info['id']['configuration']
                runtime_dist_name = ru_info['id']['internal']
                ru_config = {
                    "configuration_id": get_id_from_dist_name(configuration_dist_name),
                    "configuration_object": get_substring_from_dist_name(configuration_dist_name, start=-1, end=None),
                    "configuration_dist_name": configuration_dist_name,
                    "runtime_dist_name": runtime_dist_name
                }
                return ru_config
        raise RadioUnitNotFound(f"No Radio Unit SN: {tl_config_serial_number} in BTS configuration")

    @login_logout
    def _get_unused_radios_ids(self, bts_id=0, du_id=0):
        """
        Get list of ids of unused radios, mandatory serial number in configuration
        :param bts_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:            List of ids of unused radios
        """
        all_radios = self.get_count_of_radios(bts_id=bts_id, du_id=du_id)
        rus_info = self._get_all_rus_info(bts_id=bts_id, du_id=du_id)
        ru_serial = []
        ru_ids = []

        for radio in rus_info:
            ru_serial.append(radio.get("serialNumber"))

        for radio_id in range(all_radios):
            config_serial_number = tl_config.get_radio_serial_number(bts_id=bts_id, du_id=du_id, ru_id=radio_id)
            if config_serial_number not in ru_serial:
                ru_ids.append(radio_id)

        return ru_ids

    @login_logout
    def turn_off_unused_radios(self, bts_id=0, du_id=0):
        """
        Turn off not used radios before execution
        :param bts_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:
        """
        self._turn_on_off_unused_radios(operation='off', bts_id=bts_id, du_id=du_id)

    def _turn_on_off_unused_radios(self, operation, bts_id, du_id):
        operation = operation.upper()
        ru_ids = self._get_unused_radios_ids(bts_id=bts_id, du_id=du_id)
        obj_pdu = pdu()
        pdus = self._setup_pdu_for_all_rus(ru_ids=ru_ids, bts_id=bts_id, du_id=du_id)
        for pdu_alias in pdus:
            for pdu_ru_ids in pdus[pdu_alias]:
                radio_unit_id = pdu_ru_ids['ru_id']
                port_nr = pdu_ru_ids['pdu_port']
                try_perform_operation_on_pdu(operation=obj_pdu.power_off,
                                             port=port_nr,
                                             pdu_device=pdu_alias)

                time.sleep(5)
                port_status = try_perform_operation_on_pdu(operation=obj_pdu.get_port_status,
                                                           port=port_nr,
                                                           pdu_device=pdu_alias)
                if port_status.upper() == operation:
                    logging.info(f"Port {port_nr} powered {operation} for RU{radio_unit_id}")
                else:
                    raise WrongPduStatus(f"Port {port_nr} is not {operation} for RU{radio_unit_id}")

        for pdu_alias in pdus:
            obj_pdu.teardown_pdu(pdu_device=pdu_alias)

    def _setup_pdu_for_all_rus(self, ru_ids, bts_id, du_id):
        pdus = {}
        for radio_unit_id in ru_ids:
            pdu_alias, port_nr = self._radio_pdu_setup(bts_id=bts_id, du_id=du_id, ru_id=radio_unit_id,
                                                       already_setup_pdus=pdus)
            if pdu_alias not in pdus:
                pdus[pdu_alias] = []
            pdus[pdu_alias].append({'pdu_port': port_nr, 'ru_id': radio_unit_id})
        return pdus

    @login_logout
    def turn_on_unused_radios(self, bts_id=0, du_id=0):
        """
        Turn on radios after execution
        :param bts_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:
        """
        self._turn_on_off_unused_radios(operation='on', bts_id=bts_id, du_id=du_id)

    def get_all_radio_unit_info(self, bts_id=0, du_id=0, skip_ru_if_not_configured=False, radio_type='all'):
        """
        Get all Radio Unit info from BTS info

        :param bts_id:                    BTS id - related to Test Line configuration. Default: 0
        :type bts_id:                     int
        :param du_id:                     DU id - related to Test Line configuration - gnb.dus[]. Default: 0
        :param skip_ru_if_not_configured: If parameter is set to True then keyword will skip RU if it is not configured.
                                          If parameter is set to False then keyword will raise an exception if RU is not
                                          configured.
        :type skip_ru_if_not_configured:  bool
        :param radio_type:                'rmod' or 'asirmod' or 'all'
        :type radio_type:                 str
        :rtype:                           dict
        """
        rus_info = self._get_all_rus_info(bts_id=bts_id, du_id=du_id, radio_type=radio_type)
        filtered_rus_info = []
        for _ru_info in rus_info:
            if 'configuration' not in _ru_info['id']:
                if skip_ru_if_not_configured:
                    logging.debug('{} object was skipped. It is a runtime object.'.format(_ru_info['id']['internal']))
                    continue
                else:
                    logging.debug('There is RU connected but not configured: {}.'.format(_ru_info['id']['internal']))
            filtered_rus_info.append(_ru_info)

        return filtered_rus_info

    @login_logout
    def verify_radio_unit_statuses(self, bts_id=0, du_id=0, ru_id=1, radio_type='rmod', ru_info=None,
                                   availability_status=None,
                                   operational_state=None,
                                   administrative_state=None,
                                   procedural_status=None,
                                   usage_state=None,
                                   power_state=None,
                                   skip_ru_if_not_configured=True):
        """
        Verify RU statuses.
        If you would like to omit checking certain status/state, please provide None value.
        You can also provide status/state as regex eg re.compile(r'online|degraded')

        :param bts_id:  ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param ru_id:                   ID of radio unit. Default: 1
                                        If flag skip_ru_if_not_configured will be set to False,
                                        please provide runtime ru_id to find not configured Radio units.
        :param radio_type:              "rmod" or "asirmod"
        :param ru_info: dict -          output from bts_info for particular RU,
                                        if None, ru_info is get automatically from WeBEM
        :param availability_status:     expected availabilityStatus of Radio Unit
        :param operational_state:       expected operationalState of Radio Unit
        :param administrative_state:    expected administrativeState of Radio Unit
        :param procedural_status:       expected proceduralStatus of Radio Unit
        :param usage_state:             expected usageState of Radio Unit
        :param power_state:             expected powerState of Radio Unit
        :param skip_ru_if_not_configured:   If parameter is set to True then keyword will skip RU if it is not configured.
                                            If parameter is set to False then keyword will search by configured ru id,
                                            if is doesn't find configured id, will search by runtime ru id.
                                            If keyword doesn't find any of them will raise an exception.
        :return:        None
        """
        passed_args = copy(locals())
        var_key_mapping = {
            'availability_status': "availabilityStatus",
            'operational_state': "operationalState",
            'administrative_state': "administrativeState",
            'procedural_status': "proceduralStatus",
            'usage_state': "usageState",
            'power_state': "powerState"
        }
        expected_statuses = {}
        for arg_name, arg_value in passed_args.items():
            if arg_name in var_key_mapping.keys() and arg_value is not None:
                expected_statuses[var_key_mapping[arg_name]] = arg_value

        ru_name = '{}-{}'.format(radio_type.upper(), ru_id)
        if ru_info is None:
            ru_id = int(ru_id)
            rus_info = self.get_all_radio_unit_info(bts_id=bts_id, du_id=du_id,
                                                    skip_ru_if_not_configured=skip_ru_if_not_configured,
                                                    radio_type=radio_type)
            for _ru_info in rus_info:
                if self._get_ru_object_name_from_dist_name(dist_name=_ru_info['id']['configuration']) == ru_name:
                    ru_info = _ru_info
            if ru_info is None and not skip_ru_if_not_configured:
                for _ru_info in rus_info:
                    if self._get_ru_object_name_from_dist_name(dist_name=_ru_info['id']['internal']) == ru_name:
                        ru_info = _ru_info
            if ru_info is None:
                raise ValueError("Unable to find RU information for {}".format(ru_name))

        logging.info("Verify RU statuses for {}".format(ru_name))

        if not expected_statuses:
            raise ValueError("Expected statuses are empty - please pass at least one of status/state to check")
        unify_statuses(ru_info['status'], required_keys=expected_statuses.keys())
        verify_statuses(expected_statuses=expected_statuses, received_statuses=ru_info['status'], device=ru_name)
        logging.info("All Radio Unit statuses are as expected")

    @login_logout
    def verify_all_radio_units_statuses(self, bts_id=0, du_id=0, radio_type='all', skip_ru_if_not_configured=False,
                                        availability_status=None,
                                        operational_state=None,
                                        administrative_state=None,
                                        procedural_status=None,
                                        usage_state=None,
                                        power_state=None):
        """
        Verify All RUs statuses.
        If you would like to omit checking certain status/state, please provide None value.
        You can also provide status/state as regex eg re.compile(r'online|degraded')

        :param bts_id:  ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param radio_type:              "rmod", "asirmod" or "all" if you want to include all RUs. Default: "all"
        :param skip_ru_if_not_configured: If parameter is set to True then keyword will skip RU if it is not configured.
                                          If parameter is set to False then keyword will raise an exception if RU is not
                                          configured.
        :param availability_status:     expected availabilityStatus of Radio Unit
        :param operational_state:       expected operationalState of Radio Unit
        :param administrative_state:    expected administrativeState of Radio Unit
        :param procedural_status:       expected proceduralStatus of Radio Unit
        :param usage_state:             expected usageState of Radio Unit
        :param power_state:             expected powerState of Radio Unit
        :return:        None
        """
        rus_info = self.get_all_radio_unit_info(bts_id=bts_id, du_id=du_id,
                                                skip_ru_if_not_configured=skip_ru_if_not_configured,
                                                radio_type=radio_type)
        if not rus_info:
            raise RUsInfoNotAvailable("RUs info is not available: {}".format(rus_info))

        all_rus_incorrect_statuses = []
        for ru_info in rus_info:
            ru_name = self._get_ru_object_name_from_dist_name(dist_name=ru_info['id']['internal'])
            ru_id = get_id_from_dist_name(ru_name)
            radio_type = self._get_ru_type_from_object_name(ru_name)
            try:
                self.verify_radio_unit_statuses(bts_id=bts_id, du_id=du_id, ru_id=int(ru_id), radio_type=radio_type,
                                                ru_info=ru_info,
                                                availability_status=availability_status,
                                                operational_state=operational_state,
                                                administrative_state=administrative_state,
                                                procedural_status=procedural_status,
                                                usage_state=usage_state,
                                                power_state=power_state,
                                                skip_ru_if_not_configured=skip_ru_if_not_configured)
            except IncorrectStatuses as e:
                all_rus_incorrect_statuses.append(e)
                logging.debug(e)

        if all_rus_incorrect_statuses:
            all_dist_names = [e.device for e in all_rus_incorrect_statuses]
            logging.info("RUs with wrong statuses: {}".format(sorted(all_dist_names)))
            raise IncorrectRUsStatuses(all_rus_incorrect_statuses)

        logging.info("All RUs statuses are as expected")

    @login_logout
    def get_all_radio_units_with_statuses(self, bts_id=0, du_id=0, radio_type='all', skip_ru_if_not_configured=False,
                                          availability_status=None,
                                          operational_state=None,
                                          administrative_state=None,
                                          procedural_status=None,
                                          usage_state=None,
                                          power_state=None):
        """
        Get all Radio Units matching specific status criteria.
        Returns only RUs that match ALL provided status parameters.
        If no status parameters provided, returns all RUs.

        :param bts_id:                    BTS id - related to Test Line configuration. Default: 0
        :param du_id:                     DU id - related to Test Line configuration - gnb.dus[]. Default: 0
        :param radio_type:                'rmod', 'asirmod' or 'all'. Default: 'all'
        :param skip_ru_if_not_configured: If parameter is set to True then keyword will skip RU if it is not configured.
                                          If parameter is set to False then keyword will raise an exception if RU is not
                                          configured. Default: False
        :param availability_status:       Filter by availabilityStatus (e.g., 'online', 'offline', 'notinstalled'). Default: None
        :param operational_state:         Filter by operationalState (e.g., 'enabled', 'disabled'). Default: None
        :param administrative_state:      Filter by administrativeState (e.g., 'unlocked', 'locked'). Default: None
        :param procedural_status:         Filter by proceduralStatus (e.g., 'configured'). Default: None
        :param usage_state:               Filter by usageState (e.g., 'active', 'idle'). Default: None
        :param power_state:               Filter by powerState. Default: None
        :return:                          List of RU info dictionaries matching the status criteria
        :raises RUsInfoNotAvailable:      If RUs info is not available from BTS
        """

        rus_info = self.get_all_radio_unit_info(bts_id=bts_id, du_id=du_id,
                                                skip_ru_if_not_configured=skip_ru_if_not_configured,
                                                radio_type=radio_type)

        if not rus_info:
            raise RUsInfoNotAvailable("RUs info is not available: {}".format(rus_info))

        all_rus_with_stauses = []
        for ru_info in rus_info:
            ru_name = self._get_ru_object_name_from_dist_name(dist_name=ru_info['id']['internal'])
            ru_id = get_id_from_dist_name(ru_name)
            radio_type = self._get_ru_type_from_object_name(ru_name)
            try:
                self.verify_radio_unit_statuses(bts_id=bts_id, du_id=du_id, ru_id=int(ru_id), radio_type=radio_type,
                                                ru_info=ru_info,
                                                availability_status=availability_status,
                                                operational_state=operational_state,
                                                administrative_state=administrative_state,
                                                procedural_status=procedural_status,
                                                usage_state=usage_state,
                                                power_state=power_state,
                                                skip_ru_if_not_configured=skip_ru_if_not_configured)
            except IncorrectStatuses as e:
                logging.debug(e)
                continue
            all_rus_with_stauses.append(ru_info)
        return all_rus_with_stauses

    @login_logout
    def get_all_notinstalled_radio_units(self, bts_id=0, du_id=0, radio_type='all', skip_ru_if_not_configured=False):
        """
        Get all Radio Units with 'notinstalled' availabilityStatus.

        :param bts_id:                    BTS id - related to Test Line configuration. Default: 0
        :param du_id:                     DU id - related to Test Line configuration - gnb.dus[]. Default: 0
        :param radio_type:                'rmod', 'asirmod' or 'all'. Default: 'all'
        :param skip_ru_if_not_configured: If parameter is set to True then keyword will skip RU if it is not configured.
                                          If parameter is set to False then keyword will raise an exception if RU is not
                                          configured. Default: False
        :return:                          List of RU info dictionaries with 'notinstalled' status
        :raises RUsInfoNotAvailable:      If RUs info is not available from BTS
        """

        return self.get_all_radio_units_with_statuses(bts_id=bts_id, du_id=du_id,
                                                      radio_type=radio_type,
                                                      skip_ru_if_not_configured=skip_ru_if_not_configured,
                                                      availability_status='notinstalled')

    @login_logout
    def wait_for_radio_unit_statuses(self, bts_id=0, du_id=0, ru_id=1, radio_type='rmod',
                                     availability_status=None,
                                     operational_state=None,
                                     administrative_state=None,
                                     procedural_status=None,
                                     usage_state=None,
                                     power_state=None, timeout=180, interval=10):
        """
        Verify RU statuses during timeout.
        If you would like to omit checking certain status/state, please provide None value.
        You can also provide status/state as regex eg re.compile(r'online|degraded')

        :param bts_id:  ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param ru_id:                ID of radio unit. Default: 1
        :param radio_type:              "rmod" or "asirmod"
        :param availability_status:     expected availabilityStatus of Radio Unit
        :param operational_state:       expected operationalState of Radio Unit
        :param administrative_state:    expected administrativeState of Radio Unit
        :param procedural_status:       expected proceduralStatus of Radio Unit
        :param usage_state:             expected usageState of Radio Unit
        :param power_state:             expected powerState of Radio Unit

        :param timeout:     wait for expected status until timeout
        :param interval:    wait additional time after failed execution, before next attempt
        :return:            None
        """
        start_time = time.time()
        last_exception = None
        end_time = start_time + time_to_seconds(time=timeout)
        interval_in_seconds = time_to_seconds(time=interval)
        while time.time() < end_time:
            try:
                self.verify_radio_unit_statuses(bts_id=bts_id, du_id=du_id, ru_id=ru_id, radio_type=radio_type,
                                                availability_status=availability_status,
                                                operational_state=operational_state,
                                                administrative_state=administrative_state,
                                                procedural_status=procedural_status,
                                                usage_state=usage_state,
                                                power_state=power_state)
                break
            except IncorrectStatuses as e:
                last_exception = e
                time.sleep(interval_in_seconds)
        else:
            last_exception.additional_message = "The timeout has passed, and not all RU statuses are as expected"
            raise last_exception

    @login_logout
    def wait_for_all_radio_unit_statuses(self, bts_id=0, du_id=0, radio_type='all',
                                         availability_status=None,
                                         operational_state=None,
                                         administrative_state=None,
                                         procedural_status=None,
                                         usage_state=None,
                                         power_state=None,
                                         skip_ru_if_not_configured=False, timeout=180, interval=10):
        """
        Verify all RU statuses during timeout.
        If you would like to omit checking certain status/state, please provide None value.
        You can also provide status/state as regex eg re.compile(r'online|degraded')

        :param bts_id:  ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param radio_type:              "rmod" or "asirmod"
        :param availability_status:     expected availabilityStatus of Radio Unit
        :param operational_state:       expected operationalState of Radio Unit
        :param administrative_state:    expected administrativeState of Radio Unit
        :param procedural_status:       expected proceduralStatus of Radio Unit
        :param usage_state:             expected usageState of Radio Unit
        :param power_state:             expected powerState of Radio Unit
        :param skip_ru_if_not_configured: If parameter is set to True then keyword will skip RU if it is not configured.
                                          If parameter is set to False then keyword will raise an exception if RU is not
                                          configured.
        :param timeout:     wait for expected status until timeout
        :param interval:    wait additional time after failed execution, before next attempt
        :return:            None
        """
        start_time = time.time()
        last_exception = None
        end_time = start_time + time_to_seconds(time=timeout)
        interval_in_seconds = time_to_seconds(time=interval)
        while time.time() < end_time:
            try:
                self.verify_all_radio_units_statuses(bts_id=bts_id, du_id=du_id, radio_type=radio_type,
                                                     availability_status=availability_status,
                                                     operational_state=operational_state,
                                                     administrative_state=administrative_state,
                                                     procedural_status=procedural_status,
                                                     usage_state=usage_state,
                                                     power_state=power_state,
                                                     skip_ru_if_not_configured=skip_ru_if_not_configured)
                break
            except (IncorrectRUsStatuses, RUsInfoNotAvailable) as e:
                last_exception = e
                time.sleep(interval_in_seconds)
        else:
            last_exception.additional_message = "The timeout has passed, and not all RUs statuses are as expected"
            raise last_exception

