    def _get_configured_ru_dist_name(self, bts_id, ru_id, du_id=0, radio_type='rmod'):
        """
        Get whole configured distName for specified radio unit.

        :param bts_id:          BTS id - related to Test Line configuration. Default: 0
        :type bts_id:           int
        :param ru_id:           ID of radio unit. Default: 1
        :type ru_id:            int
        :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param radio_type:      'rmod' or 'asirmod'
        :type radio_type:       str
        :return:                distName as string
        :rtype:                 str
        """
        rus_info = self._get_all_rus_info(bts_id=bts_id, du_id=du_id, radio_type=radio_type)
        for ru_info in rus_info:
            if 'configuration' not in ru_info['id']:
                logging.warning('There is RU connected but not configured: {}. Object skipped'
                                .format(ru_info['id']['internal']))
                continue
            ru_dist_name = ru_info['id']['configuration']
            radio_id = get_id_from_dist_name(dist_name=ru_dist_name)
            if int(radio_id) == int(ru_id):
                return ru_dist_name

    def _get_runtime_ru_dist_name(self, bts_id, ru_id, du_id=0, radio_type='rmod'):
        """
        Get whole runtime distName for specified radio unit.

        :param bts_id:          BTS id - related to Test Line configuration. Default: 0
        :type bts_id:           int
        :param ru_id:           ID of radio unit. Default: 1
        :type ru_id:            int
        :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param radio_type:      'rmod' or 'asirmod'
        :type radio_type:       str
        :return:                distName as string
        :rtype:                 str
        """
        rus_info = self._get_all_rus_info(bts_id=bts_id, du_id=du_id, radio_type=radio_type)
        for ru_info in rus_info:
            ru_dist_name = ru_info['id']['internal']
            radio_id = get_id_from_dist_name(dist_name=ru_dist_name)
            if int(radio_id) == ru_id:
                return ru_dist_name

    @login_logout
    def reset_radio_unit(self, bts_id=0, radio_unit_id=1, du_id=0, timeout=600, reset_type='Soft',
                         force_radio_reset=False, radio_type='rmod', graceful_cell_shutdown=False):
        """
        Reset radio unit with specified number from BTS side.
        :param bts_id:            BTS id - related to Test Line configuration. Default: 0
        :type bts_id:             int
        :param radio_unit_id:     ID of radio unit. Default: 1
        :type radio_unit_id:      int
        :param du_id:             DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param timeout:           defaults to 600s
        :param reset_type:        Reset type; can be Hard, Warm or Soft. Defaults to Soft
        :param force_radio_reset: Parameter to force radio reset. Defaults to False. Pass if other than default
        :param radio_type:        'rmod' or 'asirmod'
        :type radio_type:         str
        :param graceful_cell_shutdown:  Perform reset procedure with graceful cell shutdown.
        :type graceful_cell_shutdown:   bool
        :return:                  None
        """
        dist_name = self._get_configured_ru_dist_name(bts_id=bts_id, ru_id=radio_unit_id, du_id=du_id,
                                                      radio_type=radio_type)
        alias = self.rest_alias.format(bts_id, du_id)
        if force_radio_reset:
            self.admin.reset_unit(dist_name=dist_name, timeout=timeout, connection=alias, reset_type=reset_type,
                                  force_radio_reset=force_radio_reset, graceful_cell_shutdown=graceful_cell_shutdown)
        else:
            self.admin.reset_unit(dist_name=dist_name, timeout=timeout, connection=alias, reset_type=reset_type,
                                  graceful_cell_shutdown=graceful_cell_shutdown)

    @login_logout
    def reset_all_radio_unit(self, bts_id=0, du_id=0, timeout=120,
                             reset_type='Soft', force_radio_reset=False, radio_type='all'):
        """
        Reset all radio units on gNB.
        :param bts_id:            BTS id - related to Test Line configuration. Default: 0
        :type bts_id:             int
        :param du_id:             DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :type du_id:              int
        :param timeout:           defaults to 120s
        :type timeout:            int
        :param reset_type:        Reset type; can be Hard, Warm or Soft. Defaults to Soft
        :param force_radio_reset: Parameter to force radio reset. Defaults to False. Pass if other than default
        :param radio_type:        "rmod", "asirmod" or "all" if you want to include all RUs. Default: "all"
        :type radio_type:         str
        :return:                  None
        """
        all_ru_ids = self._get_all_radio_ids(bts_id=bts_id, du_id=du_id, radio_type=radio_type)
        for ru_type in all_ru_ids:
            for ru_id in all_ru_ids[ru_type]:
                self.reset_radio_unit(radio_unit_id=ru_id, timeout=timeout, reset_type=reset_type,
                                      force_radio_reset=force_radio_reset, bts_id=bts_id, du_id=du_id,
                                      radio_type=ru_type)

