    def get_count_of_radio_extension_modules(self, bts_id=0, du_id=0, ru_id=None):
        """
        Get count of radio extension modules from testline configuration under specific ru, or if ru_id = None
        get count of all radio extension modules
        :param bts_id:  BTS id - related to Test Line configuration.
        :param du_id:   DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param ru_id:   Radio unit id
        :return:        count of radio extension modules
        """
        if ru_id is None:
            number_of_radio_extension_modules = 0
            number_of_ru = tl_config.get_count_of_radios(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
            for radio_unit_id in range(number_of_ru):
                number_of_radio_extension_modules += self.get_count_of_radio_extension_modules(bts_id=bts_id,
                                                                                               du_id=du_id,
                                                                                               ru_id=radio_unit_id)
        else:
            number_of_radio_extension_modules = tl_config.get_count_of_ru_extensions(bts_id=bts_id,
                                                                                     du_id=du_id,
                                                                                     ru_id=ru_id,
                                                                                     bts_type=self.bts_type)
        return number_of_radio_extension_modules

    def get_count_of_radios(self, bts_id=0, du_id=0):
        """
        Get count of radios in Test Line configuration
        :param bts_id:  BTS id - related to Test Line configuration.
        :param du_id:   DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:        count of radios
        """
        number_of_ru = tl_config.get_count_of_radios(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        return number_of_ru

    @login_logout_GUI
    def get_radio_extensions_ids(self, bts_id=0, du_id=0, ru_id=None):
        """
        Get IDs of extensions connected to given radio unit.
        :param bts_id:  BTS id - related to Test Line configuration.
        :param du_id:   DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param ru_id:   RMOD ID; if None return extensions ids for all radio units
        :return:        list of RMOD IDs for given ru_id or dict with ru_ids as keys
        """
        gui_alias = self.gui_alias.format(bts_id, du_id)
        mrbts_id = self.get_bts_instance_id(bts_id, du_id)
        ext_count = self.get_count_of_radio_extension_modules(bts_id=bts_id, du_id=du_id)
        logging.debug("Number of extensions: {}\n".format(ext_count))
        radio_to_ext_map = {}
        for loglink_id in range(1, ext_count + 1):
            dist_name = "MRBTS-{}/EQM-1/HWTOP-1/LOGLINK-{}".format(mrbts_id, loglink_id)
            ru_endpoint = self.gui_coam.get_parameter_value(dist_name,
                                                            filter_param="First endpoint distinguished Name",
                                                            abbr="firstEndpointDN",
                                                            sbts=gui_alias)
            ext_endpoint = self.gui_coam.get_parameter_value(dist_name,
                                                             filter_param="Second endpoint distinguished name",
                                                             abbr="secondEndpointDN",
                                                             sbts=gui_alias)
            radio_id = ru_endpoint.split("RMOD-")[1]
            ext_id = ext_endpoint.split("RMOD-")[1]
            if radio_id not in radio_to_ext_map.keys():
                radio_to_ext_map[radio_id] = [ext_id]
            else:
                radio_to_ext_map[radio_id].append(ext_id)
        logging.debug("RU MAPPING: {}".format(radio_to_ext_map))
        if radio_to_ext_map and ru_id is not None:
            return radio_to_ext_map[str(ru_id)]
        else:
            return radio_to_ext_map

    def power_reset_radio_unit(self, bts_id=0, radio_unit_id=None, du_id=0):
        """
        Power reset Radio Unit using pdu.
        :param bts_id:           int, BTS id - related to Test Line configuration.
        :param radio_unit_id:    position of RU in rus table from Test Line configuration.
                                 If None all radio units are reset.
        :param du_id:            DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        """
        self._radio_unit_power_off_on(operation='off', bts_id=bts_id, radio_unit_id=radio_unit_id,
                                      du_id=du_id, confirm=True)
        time.sleep(5)
        self._radio_unit_power_off_on(operation='on', bts_id=bts_id, radio_unit_id=radio_unit_id,
                                      du_id=du_id, confirm=True)

    @login_logout
    def verify_if_rau_and_rac_are_online(self, bts_id=0, du_id=0):
        """
        Verify is RAC and RAU are online
        :param bts_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        """
        bts_info = self.admin.get_bts_info(connection=self.rest_alias.format(bts_id, du_id))
        rac_status = bts_info['basebandModules'][0]['status']
        rau_status = bts_info['systemModules'][0]['status']
        unify_statuses(rac_status, required_keys=['availabilityStatus'])
        unify_statuses(rau_status, required_keys=['availabilityStatus'])

        if rac_status['availabilityStatus'] != 'online' and rau_status['availabilityStatus'] != "online":
            raise ComponentIsNotOnline("RAU and RAC should be online, but are: RAU is {} and RAC is {}"
                                       .format(rau_status['availabilityStatus'], rac_status['availabilityStatus']))

