    def _radio_pdu_setup(self, bts_id=0, du_id=0, ru_id=0, timeout=90, already_setup_pdus=None):
        """
        Prepares PDU configuration for RU and returns a tuple of PDU object and prepared PDU configuration for specific
        PDU type.
        :param bts_id:          BTS ID - related to TL configuration
        :param du_id:           Distributed Unit ID
        :param ru_id:           Radio Unit ID
        :param timeout:         Timeout for getting connection/sending requests
        :return:                Tuple of set up PDU object and prepared PDU configuration.
        """
        obj_pdu = pdu()
        bts_conf = self.get_bts_config(bts_id)
        rus = tl_config._get_rus(bts=bts_conf, du_id=du_id, bts_type=self.bts_type)
        pdu_config = rus[int(ru_id)].pdu_port
        ru_pdu = pdu_config.pdu
        alias = ru_pdu.addr
        port_nr = pdu_config.port_no
        if not (already_setup_pdus is not None and alias in already_setup_pdus):
            obj_pdu.setup_pdu(model=ru_pdu, timeout=timeout, alias=alias)
        return alias, port_nr

    def _radio_unit_power_off_on(self, operation, bts_id=0, radio_unit_id=None, du_id=0, confirm=True,
                                 check_status_before=False):
        obj_pdu = pdu()
        operation = operation.upper()
        operation_method = obj_pdu.power_on if operation == "ON" else obj_pdu.power_off
        if radio_unit_id is None:
            number_of_ru = tl_config.get_count_of_radios(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
            list_of_ru_ids = list(range(number_of_ru))
        else:
            list_of_ru_ids = [radio_unit_id]

        ports_power_on_before = {}
        pdus = self._setup_pdu_for_all_rus(ru_ids=list_of_ru_ids, bts_id=bts_id, du_id=du_id)
        for pdu_alias in pdus:
            for pdu_ru_ids in pdus[pdu_alias]:
                port_nr = pdu_ru_ids['pdu_port']
                if check_status_before:
                    port_status = try_perform_operation_on_pdu(operation=obj_pdu.get_port_status,
                                                               port=port_nr,
                                                               pdu_device=pdu_alias)
                    logging.debug(f"Status of port {port_nr} before change: {port_status}")
                    if port_status.upper() == operation:
                        logging.info(f"Already {operation} - Skipping power {operation} procedure")
                        if pdu_alias not in ports_power_on_before:
                            ports_power_on_before[pdu_alias] = []
                        ports_power_on_before[pdu_alias].append(port_nr)
                        continue
                try_perform_operation_on_pdu(operation=operation_method,
                                             port=port_nr,
                                             pdu_device=pdu_alias)
        if confirm:
            time.sleep(10)
            for pdu_alias in pdus:
                for pdu_ru_ids in pdus[pdu_alias]:
                    radio_unit_id = pdu_ru_ids['ru_id']
                    port_nr = pdu_ru_ids['pdu_port']
                    if ports_power_on_before.get(pdu_alias) and port_nr in ports_power_on_before[pdu_alias]:
                        continue
                    port_status = try_perform_operation_on_pdu(operation=obj_pdu.get_port_status,
                                                               port=port_nr,
                                                               pdu_device=pdu_alias)

                    if port_status.upper() == operation:
                        logging.info(f"Port {port_nr} powered {operation} for RU{radio_unit_id}")
                    else:
                        raise WrongPduStatus(f"Port {port_nr} is not {operation} for RU{radio_unit_id}")

        for pdu_alias in pdus:
            obj_pdu.teardown_pdu(pdu_device=pdu_alias)

    def radio_unit_power_off(self, bts_id=0, radio_unit_id=None, du_id=0, confirm=True, check_status_before=False):
        """
        Power off radio unit using PDU
        :param bts_id:         BTS id - related to Test Line configuration. Default: 0
        :param radio_unit_id:  position of RU in rus table from Test Line configuration.
                               If None all RUs are powered off.
        :param du_id:          DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param confirm:        if true set value will be checked afterwards and if it is not set the exception is raised
        :param check_status_before: check status of PDU port before power OFF - and if OFF skip executing power off
        """
        self._radio_unit_power_off_on(operation='off', bts_id=bts_id, radio_unit_id=radio_unit_id,
                                      du_id=du_id, confirm=confirm, check_status_before=check_status_before)

    def radio_unit_power_on(self, bts_id=0, radio_unit_id=None, du_id=0, confirm=True, check_status_before=False):
        """
        Power on radio unit using PDU
        :param bts_id:         BTS id - related to Test Line configuration. Default: 0
        :param radio_unit_id:  position of RU in rus table from Test Line configuration.
                               If None all RUs are powered on.
        :param du_id:          DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param confirm:        if true set value will be checked afterwards and if it is not set the exception is raised
        :param check_status_before: check status of PDU port before power ON - and if ON skip executing power on
        """
        self._radio_unit_power_off_on(operation='on', bts_id=bts_id, radio_unit_id=radio_unit_id,
                                      du_id=du_id, confirm=confirm, check_status_before=check_status_before)

    @staticmethod
    def _run_cmd_with_sudo_su(ru_obj, cmd):
        """
        Runs given cmd with sudo su. Example: sudo su rm -r /path/some_dir
        :param ru_obj:          RU object on which given cmd will be executed
        :param cmd:             Command name with necessary parameters
        :return                 sudo su cmd execution output
        """
        su_cmd = ru_obj.get_cmd(cmd_name="su", cmd_params={'cmd_object': cmd})
        sudo_su_cmd = ru_obj.get_cmd(cmd_name="sudo", cmd_params={'cmd_object': su_cmd})
        return sudo_su_cmd()

