    def _get_all_rus_info(self, bts_id=0, du_id=0, radio_type='all', bts_info=None, connection=None):
        """
        Get info of all RUs
        :param bts_id:          ID of gNB/eNB, default 0
        :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param radio_type:      "rmod", "asirmod" or "all" if you want to include all RUs. Default: "all"
        :type radio_type:       str
        :param bts_info:        BTS info dictionary. If None get it from REST API
        :param connection:      REST API connection alias. If None use default one.
        :return:                List of all radio units info
        """
        rus_info = []
        if bts_info is None:
            bts_info = self.admin.get_bts_info(
                connection=self.get_admin_connection_alias(bts_id, du_id=du_id, connection=connection))
        bts_rus_info = bts_info["radioModules"]
        rus = ["rmod", "asirmod"] if radio_type == 'all' else [radio_type]
        for ru in rus:
            rus_info.extend(bts_rus_info[ru])

        return rus_info

    @staticmethod
    def _get_ru_type_from_object_name(ru_object_name):
        ru_pattern = re.search(r'(?P<RU_TYPE>\w+)(_\w)?-', ru_object_name)
        ru_type = ru_pattern.group('RU_TYPE')
        return ru_type

    @staticmethod
    def _get_ru_object_name_from_dist_name(dist_name):
        ru_pattern = re.search(r'(?P<RU_OBJECT_NAME>\w*RMOD)(_\w)?-(?P<ID>\d+)$', dist_name)
        ru_object_name = "{}-{}".format(ru_pattern.group('RU_OBJECT_NAME'), ru_pattern.group('ID'))
        return ru_object_name

    def __get_all_radios(self, mode='id', bts_id=0, du_id=0, extension=False, radio_type='all', bts_info=None):
        """
        Get dictionary of radio unit types and ids or list of dist_names. Depend on selected mode.
        :param mode:        "id" or "dist_name" - if you want to get radio unit id or dist name
        :param bts_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param extension:   If True get ids for all radio units - including extensions.
        :param radio_type:  "rmod", "asirmod" or "all" if you want to include all RUs. Default: "all"
        :return:            Dictionary of all available radio types and unit IDs or list of dist names
        """
        ru_types = ['rmod', 'asirmod'] if radio_type == 'all' else [radio_type]
        rus_type_ids = {}
        dist_names = []
        value_to_return = rus_type_ids if mode == 'id' else dist_names
        for ru_type in ru_types:
            rus_type_ids[ru_type] = []
            rus_info = self._get_all_rus_info(bts_id=bts_id, du_id=du_id, radio_type=ru_type, bts_info=bts_info)
            for ru_info in rus_info:
                if 'configuration' not in ru_info['id']:
                    logging.warning('There is RU connected but not configured: {}. Object skipped'
                                    .format(ru_info['id']['internal']))
                    continue
                if self._is_extension_radio(ru_info) and not extension:
                    continue
                if mode == 'id':
                    radio_id = get_id_from_dist_name(dist_name=ru_info['id']['configuration'])
                    if radio_id is None:
                        raise DataNotAvailable("Radio Unit ID not found")
                    rus_type_ids[ru_type].append(int(radio_id))
                else:
                    dist_names.append(ru_info['id']['configuration'])

        return value_to_return

    def _get_all_radio_ids(self, bts_id=0, du_id=0, extension=False, radio_type='all', bts_info=None):
        """
        Get dictionary of radio unit types and ids
        :param bts_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param extension:   If True get ids for all radio units - including extensions.
        :param radio_type:  "rmod", "asirmod" or "all" if you want to include all RUs. Default: "all"
        :return:            Dictionary of all available radio types and unit IDs
        """
        return self.__get_all_radios(mode='id', bts_id=bts_id, du_id=du_id, extension=extension, radio_type=radio_type,
                                     bts_info=bts_info)

    def _get_all_radio_dist_names(self, bts_id=0, du_id=0, extension=False, radio_type='all', bts_info=None):
        """
        Get all radio dist names
        :param bts_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param extension:   If True get ids for all radio units - including extensions.
        :param radio_type:  "rmod", "asirmod" or "all" if you want to include all RUs. Default: "all"
        :return:            list of dist names
        """
        return self.__get_all_radios(mode='dist_name', bts_id=bts_id, du_id=du_id, extension=extension,
                                     radio_type=radio_type, bts_info=bts_info)

    def get_all_extension_dist_names(self, bts_id=0, du_id=0):
        """
        Get list of all extension dist names
        :param bts_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:            List of extension dist names
        """
        extension_dist_names = []
        rus_info = self._get_all_rus_info(bts_id=bts_id, du_id=du_id)
        for ru_info in rus_info:
            if self._is_extension_radio(ru_info):
                extension_dist_names.append(ru_info['id']['configuration'])

        return extension_dist_names

    @staticmethod
    def _is_extension_radio(ru_info):
        _re_am_port = re.compile(r'^AM\d+$')
        for port_info in ru_info['ports']:
            if _re_am_port.search(port_info['label']):
                return True
        return False

    @load_moler_configuration_from_tl()
    def get_dhcp_leases(self, bts_id=0, du_id=0):
        """
        Get dhcp lease from file and put into dictionary
        :param bts_id:    BTS id - related to Test Line configuration. Default: 0
        :param du_id:     DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:          {78:f9:b4:9f:d3:cf} = {
                             "ip": 192.168.254.145,
                             "starts": 2020/04/15 06:40:43,
                             "ends": 2020/04/15 06:47:43,
                             "cltt": 2020/04/15 06:47:43,
                             "vendor-class-identifier": LLS-MP-1-RM,
                             "radio_variant": ECPRI_RP1,
                             'container_id': '0x1018'
                          }
        """
        bts = DeviceFactory.get_device(name=self.ssh_alias.format(bts_id, du_id))
        ssh_leases_dict = {}
        container_id = self._get_container_id_gnb2ru(dev_name=bts.name)
        bts.change_fhnet_container_id(container_id=container_id)
        if container_id is not None:
            bts.goto_state("FHNET")
            leases_file_name = 'dhcp.leases'
            lease_dir_path_v1 = r'/var/tmp/radio-dhcpd/'
            lease_dir_path_v2 = r'/ram/radio-dhcpd/'
            try:
                bts.get_cmd(cmd_name="ls", cmd_params={"path": lease_dir_path_v1})()
                lease_path = os.path.join(lease_dir_path_v1, leases_file_name)
            except CommandFailure:
                lease_path = os.path.join(lease_dir_path_v2, leases_file_name)
        else:
            bts.goto_state("FCT")
            lease_path = r'/tmp/radio-dhcpd/dhcp.leases'
        cat_cmd = bts.get_cmd(cmd_name="cat", cmd_params={"path": lease_path})
        output = cat_cmd()['LINES']
        ip_pattern = re.compile(r'\d+(?:\.\d+){3}')
        ethernet_pattern = re.compile(r'\s*hardware\s+ethernet\s+(?P<Adress>.+);')
        starts_pattern = re.compile(r'\s*starts\s+\d\s+(?P<Datetime>.+);')
        ends_pattern = re.compile(r'\s*ends\s+\d\s+(?P<Datetime>.+);')
        cltt_pattern = re.compile(r'\s*cltt\s+\d\s+(?P<Datetime>.+);')
        vendor_pattern = re.compile(r'\s*set\s+vendor-class-identifier\s=\s"+(?P<Vci>.+)";')
        radio_variant_pattern = re.compile(r'\s*set\s+radio_variant\s=\s"+(?P<Variant>.+)";')
        closing_bracket_pattern = re.compile(r'}$')
        inner_dict = dict.fromkeys(["ip", "starts", "ends", "cltt", "vendor-class-identifier", "radio_variant"])
        for lines in output:
            ips = ip_pattern.search(lines)
            ethernets = ethernet_pattern.match(lines)
            starts = starts_pattern.match(lines)
            ends = ends_pattern.match(lines)
            cltts = cltt_pattern.match(lines)
            vendor_class_identifier = vendor_pattern.match(lines)
            radio_variant = radio_variant_pattern.match(lines)
            closing_bracket = closing_bracket_pattern.match(lines)
            inner_dict['container_id'] = container_id
            if ips is not None:
                inner_dict["ip"] = ips.group(0)
            elif ethernets is not None:
                ethernet = ethernets.group('Adress')
            elif starts is not None:
                inner_dict["starts"] = starts.group('Datetime')
            elif ends is not None:
                inner_dict["ends"] = ends.group('Datetime')
            elif cltts is not None:
                inner_dict["cltt"] = cltts.group('Datetime')
            elif vendor_class_identifier is not None:
                inner_dict["vendor-class-identifier"] = vendor_class_identifier.group('Vci')
            elif radio_variant is not None:
                inner_dict["radio_variant"] = radio_variant.group('Variant')
            elif closing_bracket is not None:
                ssh_leases_dict[ethernet] = inner_dict
                inner_dict = dict.fromkeys(["ip", "starts", "ends", "cltt", "vendor-class-identifier",
                                            "radio_variant"])
        logging.debug("ssh_leases_dict: {}".format(ssh_leases_dict))
        return ssh_leases_dict

    def get_valid_dhcp_leases(self, bts_id=0, du_id=0):
        """
        Verify if current date is between start and end date from DHCP file
        :param bts_id:    BTS id - related to Test Line configuration. Default: 0
        :param du_id:     DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:          {"78:f9:b4:9f:d3:cf": {
                             "ip": 192.168.254.145,
                             "starts": 2020/04/15 06:40:43,
                             "ends": 2020/04/15 06:47:43,
                             "cltt": 2020/04/15 06:47:43,
                             "vendor-class-identifier": LLS-MP-1-RM,
                             "radio_variant": ECPRI_RP1,
                             "container_id": "0x1018"
                             }
                          }
        """
        ssh_leases_dict = self.get_dhcp_leases(bts_id=bts_id, du_id=du_id)
        time_format = "%Y/%m/%d %H:%M:%S"
        current_time_format = "%d-%m-%Y %H:%M:%S"
        bts = DeviceFactory.get_device(name=self.ssh_alias.format(bts_id, du_id))
        date_cmd = bts.get_cmd(cmd_name="date", cmd_params={'options': "-u"})
        date_time = date_cmd()
        get_time = "{} {}".format(date_time["DATE"]["FULL"], date_time["TIME"]["FULL"])
        ssh_leases_dict_valid = {}
        for key in ssh_leases_dict.keys():
            values_dict = ssh_leases_dict[key]
            start_time = time.mktime(datetime.datetime.strptime(values_dict['starts'], time_format).timetuple())
            end_time = time.mktime(datetime.datetime.strptime(values_dict['ends'], time_format).timetuple())
            current_time = time.mktime(datetime.datetime.strptime(get_time, current_time_format).timetuple())
            if (start_time <= current_time) and (current_time <= end_time):
                ssh_leases_dict_valid[key] = ssh_leases_dict[key]
        return ssh_leases_dict_valid

    @load_moler_configuration_from_tl()
    def _get_ru_ssh_params(self, number_of_ru, bts_id=0, du_id=0):
        """
        From dhcp config file get parameters which allowed ssh connection
        :param number_of_ru: number of radio unit in webem
        :param bts_id:       BTS id - related to Test Line configuration. Default: 0
        :param du_id:        DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:             {'login':root,
                              'password': asmr,
                              'expected_prompt': r'[.*hw-.*] .*?$?}
        """
        ssh_params_list = []
        for index in range(number_of_ru):
            ru = DeviceFactory.get_device(name=self.ssh_ru_alias.format(bts_id, du_id, index),
                                          establish_connection=False)
            configuration = ru.get_configurations(source_state='FHNET', dest_state='RU')
            ssh_params = {'login': configuration['command_params']['login'],
                          'password': configuration['command_params']['password'],
                          'expected_prompt': configuration['command_params']['prompt_after_login']}
            if ssh_params not in ssh_params_list:
                ssh_params_list.append(ssh_params)
        return ssh_params_list

    def verify_connection_with_all_ru(self, dhcp_dict, bts_id=0, du_id=0):
        """
        Connect via ssh with all radio units connected to BTS
        :param dhcp_dict: dictionary with dhcp config
        :param bts_id:    BTS id - related to Test Line configuration. Default: 0
        :param du_id:     DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        """
        number_of_ru_in_tl = tl_config.get_count_of_radios(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        if number_of_ru_in_tl == len(dhcp_dict.keys()):
            ssh_params_list = self._get_ru_ssh_params(number_of_ru=number_of_ru_in_tl,
                                                      bts_id=bts_id, du_id=du_id)
            logging.debug(f'SSH params list: {ssh_params_list}')
        else:
            raise WrongNumberOfRadios("Number of radios in BTS config is not equal to number of radios in DHCP config")

        for radio_index, mac_adress in enumerate(dhcp_dict):
            counter = 0
            ip_adress = dhcp_dict[mac_adress]['ip']
            for ssh_params in ssh_params_list:
                bts = DeviceFactory.get_device(name=self.ssh_alias.format(bts_id, du_id))
                if self._get_container_id_gnb2ru(bts.name):
                    logging.info("Go to state FHNET...")
                    bts.goto_state("FHNET")
                expected_prompt = r'{}'.format(ssh_params['expected_prompt'])
                ssh_cmd = self._ssh_to_ru(ip_adress, ssh_params['login'],
                                          ssh_params['password'],
                                          expected_prompt, bts_id, du_id)
                exit_cmd = bts.get_cmd(cmd_name="exit")
                try:
                    ssh_cmd()
                    logging.info("connected to RU{} from {} RUs".format(radio_index, number_of_ru_in_tl))
                    counter = 0
                    exit_cmd()
                    break
                except (CommandFailure, CommandTimeout):
                    counter += 1
                    logging.info("counter: {}".format(counter))
                    if counter == len(ssh_params_list):
                        raise SshConnectionFailed("SSH failed, couldn't login to RU with given params")
                    continue

    @load_moler_configuration_from_tl()
    def verify_configuration_parameters_in_soap_logs(self, rx_tx_parameters=None, parameters=None, bts_id=0, du_id=0):
        """
        Verify if rx and tx parameters have the same values and if other parameter is equal given value
        :param rx_tx_parameters: list of parameters to find in soap logs in rx and tx
        :param parameters:       dictionary of parameters and values to check in soap logs
        :param bts_id:           BTS id - related to Test Line configuration. Default: 0
        :param du_id:            DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        """
        soap_files = self._download_soap_file(local_dir="/tmp", bts_id=bts_id, du_id=du_id)
        for soap_file in soap_files:
            param_dict = self._get_parameter_from_soap_file(file_path=soap_file, rx_tx_parameters=rx_tx_parameters,
                                                            parameters=parameters)
            if rx_tx_parameters is not None:
                for rx_tx_parameter in rx_tx_parameters:
                    first_list_element = param_dict['tx'][rx_tx_parameter][0]
                    if all(elem == first_list_element for elem in param_dict['tx'][rx_tx_parameter]) \
                            and all(elem == first_list_element for elem in param_dict['rx'][rx_tx_parameter]):
                        continue
                    else:
                        raise WrongParameterSettings("tx and rx versions of {} are not equal".format(rx_tx_parameter))
            if parameters is not None:
                for key in parameters:
                    for index in range(len(param_dict['param'][key])):
                        parameter = param_dict['param'][key][index]
                        if int(parameter) < 0 or int(parameter) > 255:
                            raise WrongParameterSettings("{} is not between 0 and 255. Value is {}"
                                                         .format(parameters, parameter))

    def _get_parameter_from_soap_file(self, file_path, rx_tx_parameters=None, parameters=None):
        """
        For list of rx and tx parameters and dictionary of other parameters function returns dictionary with parameter
        values, divided for rx, tx, and parameter.
        :param file_path:           path to soap file
        :param rx_tx_parameters:    list of parameters to find in soap logs in rx and tx
        :param parameters:          dictionary of parameters and values to check in soap logs
        :return:                    param_dict with 3 main key, rx, tx, and param, containing dictionaries,
                                    with parameter as main key and i.e as value list of values taken from soap file
        {
            'rx':  {
                    u'cyclicPrefix': ['NORMAL_CP', 'NORMAL_CP', 'NORMAL_CP', 'NORMAL_CP'],
                    u'defaultSubcarrierSpacing': ['KHZ_120', 'KHZ_120', 'KHZ_120', 'KHZ_120']
                    },
            'param':{
                    u'fftSamplingOffset': ['16', '16', '16', '16']
                    },
            'tx':   {
                    u'cyclicPrefix': ['NORMAL_CP', 'NORMAL_CP', 'NORMAL_CP', 'NORMAL_CP', 'NORMAL_CP',  'NORMAL_CP'],
                    u'defaultSubcarrierSpacing': ['KHZ_120', 'KHZ_120', 'KHZ_120', 'KHZ_120', 'KHZ_120', 'KHZ_120']
                    }
        }
        """
        pat_start = '(?<='
        pat_end = '</parameterName><newValue>).+?(?=</newValue>)'
        param_dict = {'tx': {},
                      'rx': {},
                      'param': {}}
        log_lines = open(file_path, 'r').readlines()
        for log_line in log_lines:
            if rx_tx_parameters is not None:
                for rx_tx_parameter in rx_tx_parameters:
                    try:
                        param_dict['tx'][rx_tx_parameter]
                    except KeyError:
                        param_dict['tx'].update({rx_tx_parameter: []})
                    match_tx = re.search(r'TxArrayCarrier', log_line)
                    if match_tx is not None:
                        pattern_param = r'{}{}{}'.format(pat_start, rx_tx_parameter, pat_end)
                        param_value = re.search(pattern_param, log_line)
                        if param_value is not None:
                            param_dict['tx'][rx_tx_parameter].append(param_value.group(0))
                    try:
                        param_dict['rx'][rx_tx_parameter]
                    except KeyError:
                        param_dict['rx'].update({rx_tx_parameter: []})
                    match_rx = re.search(r'RxArrayCarrier', log_line)
                    if match_rx is not None:
                        pattern_param = r'{}{}{}'.format(pat_start, rx_tx_parameter, pat_end)
                        param_value = re.search(pattern_param, log_line)
                        if param_value is not None:
                            param_dict['rx'][rx_tx_parameter].append(param_value.group(0))
            if parameters is not None:
                for parameter in parameters:
                    try:
                        param_dict['param'][parameter]
                    except KeyError:
                        param_dict['param'].update({parameter: []})
                    pattern_param = r'{}{}{}'.format(pat_start, parameter, pat_end)
                    param_value = re.search(pattern_param, log_line)
                    if param_value is not None:
                        param_dict['param'][parameter].append(param_value.group(0))
        return param_dict

    def _download_soap_file(self, local_dir="/tmp", bts_id=0, du_id=0):
        """
        Download SOAP file with configuration, from all RU connected to tl, and save them local in
        chosen folder
        :param local_dir:   directory, where the soap file will be downloaded
        :param bts_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        """
        number_of_ru_in_tl = tl_config.get_count_of_radios(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        soap_files_list = []
        for radio_index in range(number_of_ru_in_tl):
            gnb_name = self.ssh_alias.format(bts_id, du_id)
            ru = self.get_ru_device(bts_id=bts_id, du_id=du_id, ru_id=radio_index)
            cd_cmd = ru.get_cmd(cmd_name="cd", cmd_params={'path': "/run"})
            tar_cmd = ru.get_cmd(cmd_name="gunzip", cmd_params={'archive_name': ["UnitOAM_SOAP_Log0.xml.gz"]})
            ls_cmd = ru.get_cmd(cmd_name="ls")
            cd_cmd()
            if 'UnitOAM_SOAP_Log0.xml.gz' in ls_cmd()['files']:
                tar_cmd()
            try:
                bts = DeviceFactory.get_device(name=gnb_name)
                bts.goto_state("FCT")
                download_files(local_dir=local_dir, remote_file='UnitOAM_SOAP_Log0.xml', device_name=ru.name,
                               remote_dir='/run', new_file_name="UnitOAM_SOAP_Log{}.xml".format(radio_index))
                soap_files_list.append("{}/UnitOAM_SOAP_Log{}.xml".format(local_dir, radio_index))
                return soap_files_list
            except CommandFailure:
                raise FileNotFound("There is no UnitOAM files on this RU")

    def _ssh_to_ru(self, host, login, password, expected_prompt, bts_id=0, du_id=0):
        """
        Make ssh connection to Radio Unit
        :param host:            host name from tl config ie. 192.168.255.129
        :param login:           login from tl config ie. root
        :param password:        password from tl config ie. asmr
        :param expected_prompt: expected prompt from tl config ie. r'[.*hw-.*] .*?$?}
        :param bts_id:          BTS id - related to Test Line configuration. Default: 0
        :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:
        """
        bts = DeviceFactory.get_device(name=self.ssh_alias.format(bts_id, du_id))
        ssh_cmd = bts.get_cmd(cmd_name="ssh", cmd_params={'host': host, 'login': login, 'password': password,
                                                          'expected_prompt': expected_prompt,
                                                          'allowed_newline_after_prompt': True}, check_state=True)
        return ssh_cmd

    def verify_ru_configuration_via_gui(self, bts_id=0, ru_id=0, du_id=0, radio_type='rmod'):
        """
        Comapare lists of parameters from GUI and Radio Unit for RU's and extensions, if they are equal
        :param bts_id:      bts id - related to Test Line configuration.
        :param ru_id:       Radio unit id
        :param du_id:       id related to Test Line configuration - gnb.dus[]
        :param radio_type:  'rmod' or 'asirmod'
        """
        number_of_ext = tl_config.get_count_of_ru_extensions(bts_id, du_id, ru_id=ru_id)
        if number_of_ext > 0:
            ext_info_gui = self._get_all_ext_info_via_gui(bts_id=bts_id, du_id=du_id, number_of_ext=number_of_ext,
                                                          radio_type=radio_type)
            ext_info = self._get_all_ext_info(bts_id=bts_id, du_id=du_id, number_of_ext=number_of_ext)
            for ext in ext_info_gui.keys():
                for param in ext_info_gui[ext].keys():
                    diff_list = [(ext, param, ext_info[ext][param]) for param in ext_info_gui[ext].keys() if
                                 ext_info[ext][param] != ext_info_gui[ext][param]]
                    if diff_list:
                        raise ListsAreNotEqual("Information about extensions in GUI are invalid: {}".format(diff_list))
        radio_info_gui = self._get_all_ru_info_via_gui(bts_id=bts_id, du_id=du_id)
        radio_info = self._get_all_ru_info(bts_id=bts_id, du_id=du_id)

        for radio_gui in radio_info_gui.keys():
            for radio in radio_info.keys():
                same = True
                for param in radio_info_gui[radio_gui].keys():
                    if same is True:
                        if radio_info[radio][param] != radio_info_gui[radio_gui][param]:
                            same = False
                if same is True:
                    radio_info.pop(radio)
                    break

        if radio_info:
            raise ListsAreNotEqual("Information about radio in GUI are invalid: {} {}".format(radio_info,
                                                                                              radio_info_gui))

    @load_moler_configuration_from_tl()
    def _get_all_ru_info(self, bts_id=0, du_id=0):
        """
        Get information about radio unit:  product code, hw type, serial number and make from it a dict
        :param bts_id:    bts id - related to Test Line configuration.
        :param du_id:     id related to Test Line configuration - gnb.dus[]
        :return:          'radio 1': {'Product code': u'475166A.101', 'HW version': u'101', 'Serial number': u'YK202200102'}
        """
        all_radios = self.get_count_of_radios(bts_id=bts_id, du_id=du_id)
        ru_info_path = "/mnt/factory/configs/unit/"
        radio_info = {}
        for radio_id in range(all_radios):
            ru = self.get_ru_device(bts_id=bts_id, du_id=du_id, ru_id=radio_id)
            cat_product_code = ru.get_cmd(cmd_name="cat", cmd_params={'path': "{}core_assembly_product_code.txt"
                                          .format(ru_info_path)})
            product_code = cat_product_code()['LINES']
            hw_code = str(product_code)[-5:]
            hw_code = hw_code[:3]
            serial_number = self._get_ru_serial_number(bts_id=bts_id, du_id=du_id, radio_id=radio_id)
            ru_dict = {
                "Serial number": serial_number,
                "Product code": product_code[0],
                "HW version": hw_code}
            radio_info["radio {}".format(radio_id + 1)] = ru_dict
        return radio_info

    @load_moler_configuration_from_tl()
    def _get_ru_serial_number(self, bts_id=0, du_id=0, radio_id=0):
        ru_info_path = "/mnt/factory/configs/unit/"
        ru = self.get_ru_device(bts_id=bts_id, du_id=du_id, ru_id=radio_id)
        cat_serial_number = ru.get_cmd(cmd_name="cat", cmd_params={'path': "{}core_assembly_serial_number.txt"
                                       .format(ru_info_path)})
        serial_number = cat_serial_number()['LINES']

        return serial_number[0]

    @load_moler_configuration_from_tl()
    def _get_all_ext_info(self, bts_id=0, du_id=0, number_of_ext=1):
        """
        Get information about radio unit extensions: product code, serial number and make from it a dict
        :param bts_id:            bts id - related to Test Line configuration.
        :param du_id:             id related to Test Line configuration - gnb.dus[]
        :param number_of_ext:     number of ext in configuration
        :return:                  'extension 1': {'Product code': u'475166A.101', 'Serial number': u'YK202200102'}
        """
        extension_info = {}
        all_radios = self.get_count_of_radios(bts_id=bts_id, du_id=du_id)
        for radio_id in range(all_radios):
            ru = self.get_ru_device(bts_id=bts_id, du_id=du_id, ru_id=radio_id)
            for ext_id in range(number_of_ext):
                get_ext_info = ru.get_cmd(cmd_name="run_script",
                                          cmd_params={'script_command': "am_flash -a {} -u >"
                                                                        " ext_info{}.txt".format(ext_id + 1, ext_id)})
                cat_ext_info = ru.get_cmd(cmd_name="cat",
                                          cmd_params={'path': '/home/root/ext_info{}.txt'.format(ext_id)})
                get_ext_info()
                cat = cat_ext_info()['LINES']
                for param in cat:
                    if "serial" in param:
                        serial_number = re.search(r'\'(.*?)\'', param).group(1)
                    if "unit code" in param:
                        product_code = re.search(r'\'(.*?)\'', param).group(1)
                ext_dict = {
                    "Serial number": serial_number,
                    "Product code": product_code}
                extension_info["extension {}".format(ext_id + 1)] = ext_dict
        return extension_info

