    def set_incorrect_loglink_name_and_verify_error_via_gui(self, loglinkId, incorrect_name,
                                                            error_content="EXTMOD-1",
                                                            bts_id=0, du_id=0):
        """
        Change name of existing loglink to incorrect and verify validation error
        :param loglinkId:               id of the existing loglink
        :param incorrect_name:          incorrect name of the loglink
        :param error_content:           content of validation error message to compare
        :param bts_id:                  bts id - related to Test Line configuration.
        :param du_id:                   DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:                        None
        """

        try:
            self.set_loglink_name_via_gui(loglinkId, incorrect_name, bts_id=bts_id, du_id=du_id)
        except ValidationError as e:
            errors = e.errors
            errors_keys = errors.keys()
            if len(errors_keys) > 1:
                raise Exception("Too many components report validation error: {}".format(errors))
            if len(errors[errors_keys[0]]) > 1:
                raise Exception("Too many validation errors: {}".format(errors))
            if error_content not in errors[errors_keys[0]][0]:
                raise Exception("Wrong validation error: {}".format(errors[errors_keys[0]][0]))

    def collect_ccs_shell_logs(self, bts_id=0, du_id=0, ru_id=None, log_dir=None):
        """
        Collect ccsShell logs from RU
        :param bts_id:  BTS id - related to Test Line configuration. Default: 0
        :param du_id:   DU id(Distributed Unit) - id related to Test Line configuration. Default: 0
        :param ru_id:   Position of RU in rus table from Test Line configuration. If None - run on all rus
        :param log_dir: local directory path where logs will be downloaded.
                        If None - default logs dir will be used: ${OUTPUT DIR}/Logs/<timestamp>
        """
        ru_ids = [ru_id] if ru_id else range(tl_config.get_count_of_radios(bts_id=bts_id,
                                                                           du_id=du_id,
                                                                           bts_type=self.bts_type))
        if log_dir is None:
            log_dir = get_log_path()

        for _ru_id in ru_ids:
            remote_file = self._collect_ccs_shell_logs(bts_id=bts_id, du_id=du_id, ru_id=_ru_id)
            download_files(local_dir=log_dir,
                           remote_file=os.path.basename(remote_file),
                           remote_dir=os.path.dirname(remote_file),
                           device_name=self.ssh_ru_alias.format(bts_id, du_id, _ru_id))

    @load_moler_configuration_from_tl()
    def _collect_ccs_shell_logs(self, bts_id=0, du_id=0, ru_id=0, timeout=60):
        """
        Collect ccsShell logs from RU
        :param bts_id:      BTS id - related to Test Line configuration. Default: 0
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration. Default: 0
        :param ru_id:       Position of RU in rus table from Test Line configuration. Default: 0
        :param timeout:     timeout for collecting logs
        """
        ru = self.get_ru_device(bts_id=bts_id, du_id=du_id, ru_id=ru_id)
        file_name = '{}_log.zip'.format(ru.name)
        log_path = os.path.join('/ram', file_name)
        collect_logs = ru.get_cmd(cmd_name="run_script",
                                  cmd_params={'script_command': 'ccsShell.sh log -c full -a -z {}'.format(log_path)})
        collect_logs(timeout=timeout)
        return log_path

