    def wait_for_radio_unit_online_status(self, radio_unit_id=None, timeout=300, step=20, bts_id=0, du_id=0,
                                          radio_type='rmod'):
        """
        :param radio_unit_id:  RU ID - related to RMODs configuration. If None wait for all RUs. Default: None
        :param bts_id:         BTS id - related to Test Line configuration. Default: 0
        :param timeout:        time in seconds the method waits for ru online status
        :param step:           time interval in seconds
        :param du_id:          DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param radio_type:     'rmod' or 'asirmod'
        :return:               None
        """

        logging.warning("'wait_for_radio_unit_online_status' is deprecated - please use "
                        "'wait_for_radio_unit_to_be_online'")
        start_time = time.time()
        while (time.time() - start_time) < timeout:
            try:
                if radio_unit_id is None:
                    logging.info("Checking if all RUs are online")
                    self.verify_all_radio_module_status(bts_id=bts_id, du_id=du_id)
                else:
                    logging.info("Checking if {}{} is online".format(radio_type.upper(), radio_unit_id))
                    self.verify_radio_unit_status(radio_unit_id=radio_unit_id, bts_id=bts_id, du_id=du_id,
                                                  radio_type=radio_type)
                return
            except WrongRadioModuleStatus:
                logging.warning("{}{} not online. Checking again...".format(*[radio_type.upper(), radio_unit_id]
                                if radio_unit_id is not None else ["RU", "s"]))
                time.sleep(step)
        raise WrongRadioModuleStatus("{}{} not online after {t}s of waiting".format(*[radio_type.upper(), radio_unit_id]
                                     if radio_unit_id is not None else ["RU", "s"], t=timeout))

    @login_logout
    def verify_if_all_radio_modules_online(self, raise_exception=True, bts_id=0, du_id=0, radio_type='all'):
        """
        Verify if all radio modules availability statuses are online.
        :param bts_id:          bts id - ID related to Test Line configuration.
        :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param raise_exception: Boolean which determines whether exception should be raised or not when radio is offline
        :param radio_type:      "rmod", "asirmod" or "all" if you want to include all RUs. Default: "all"
        :return:
        """

        logging.warning("'verify_if_all_radio_modules_online' is deprecated - please use "
                        "'verify_all_radio_units_are_online'")

        rus_info = self._get_all_rus_info(bts_id=bts_id, du_id=du_id, radio_type=radio_type)
        number_of_radios = len(rus_info)
        radios_not_online = []
        for radio_index in range(number_of_radios):
            ru_status = rus_info[radio_index]["status"]
            unify_statuses(ru_status, required_keys=['availabilityStatus'])
            availability_status = (ru_status["availabilityStatus"])
            if availability_status != 'online':
                radios_not_online.append(rus_info[radio_index]['id']['configuration'])

        if raise_exception and len(radios_not_online) > 0:
            raise WrongRadioModuleStatus(radios_not_online)
        return radios_not_online

    @login_logout
    def check_if_ru_has_shared_cell_with_other_rus(self, ru_id, bts_id=0, du_id=0):
        all_ru_rel = self._get_ru_cell_relation(bts_id, du_id)
        logging.debug("All RU rel: {}".format(all_ru_rel))
        selected_ru_rel = self._get_ru_rel(all_ru_rel, ru_id)
        logging.debug("Selected RU rel : {}".format(selected_ru_rel))
        for ru_rel in all_ru_rel:
            if ru_id == ru_rel['id']:
                continue
            for cell in ru_rel['cells']:
                if cell in selected_ru_rel['cells']:
                    return True
        return False

    def remove_disablerxloswa_flag_from_all_rus(self, bts_id=0, du_id=0):
        """
        Remove disable_rx_los_wa flag from all radio units if exists
        :param bts_id:          bts id - ID related to Test Line configuration.
        :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:
        """
        number_of_ru_in_tl = tl_config.get_count_of_radios(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        for ru_id in range(number_of_ru_in_tl):
            self.remove_file_from_ru_if_exists(file_path='/mnt/runtime/coco/disable_rx_los_wa', ru_id=ru_id)

    @load_moler_configuration_from_tl()
    def remove_file_from_ru_if_exists(self, file_path, ru_id, bts_id=0, du_id=0):
        """
        Remove file from radio unit if exists
        :param file_path:       absolute path of the file to be removed
        :param ru_id:           ID of radio unit
        :param bts_id:          bts id - ID related to Test Line configuration.
        :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:
        """
        ru = self.get_ru_device(bts_id=bts_id, du_id=du_id, ru_id=ru_id)
        rm_cmd_kwargs = {'cmd_name': 'rm', 'cmd_params': {'file': file_path, 'options': '-f'}}
        try:
            rm_cmd = ru.get_cmd(**rm_cmd_kwargs)
            rm_cmd()
            logging.debug(f"File '{file_path}' was removed for {format(ru.name)}")
        except CommandFailure as e:
            logging.debug(f"File '{file_path}' was not removed for {format(ru.name)} due to {e}\n"
                          f"Trying with sudo su...")
            try:
                rm_cmd = ru.get_cmd(**rm_cmd_kwargs)
                self._run_cmd_with_sudo_su(ru_obj=ru, cmd=rm_cmd)
                logging.debug(f"File '{file_path}' was removed for {format(ru.name)}")
            except CommandFailure as e:
                logging.debug(f"File '{file_path}' was not removed for {format(ru.name)} due to {e}")

    def _get_ru_cell_relation(self, bts_id=0, du_id=0, connection=None):
        """
        Get relation between RU and its cells
        :param bts_id:          bts id - ID related to Test Line configuration.
        :param du_id:           DU id(Distributed Unit) - id related to Test Line
        :param connection:      REST connection alias
        :return:                list of dictionaries with RU to cells relation
        """
        bts_info = self.admin.get_bts_info(connection=self.get_admin_connection_alias(bts_id, du_id, connection))
        rus = self._get_all_rus_info(bts_id, du_id, bts_info=bts_info, connection=connection)
        all_ru_rel = []
        for ru in rus:
            ru_dn = ru['id']['configuration']
            ru_id = get_id_from_dist_name(dist_name=ru_dn)
            all_cells = []
            for carrier in ru['carrierList']:
                cell_dist_name = get_substring_from_dist_name(carrier['id']['configuration'])
                cell_details = {
                    'id': cell_dist_name.split('/')[-1],
                    'name': get_substring_from_dist_name(cell_dist_name, start=-1, end=None),
                    'dn': cell_dist_name,
                    'runtime': get_cell_runtime_based_on_dist_name(bts_info, cell_dist_name)
                }
                if cell_details not in all_cells:
                    all_cells.append(cell_details)
            ru_rel = {
                'id': ru_id,
                'name': get_substring_from_dist_name(ru_dn, start=-1, end=None),
                'dn': ru_dn,
                'runtime': ru['id']['internal'],
                'cells': all_cells
                # 'bbmod' # maybe in the future
            }
            all_ru_rel.append(ru_rel)

        return all_ru_rel

    @staticmethod
    def _get_ru_rel(all_ru_rel, value, key_name='id'):
        for ru_rel in all_ru_rel:
            if str(ru_rel[key_name]) == str(value):
                return ru_rel


