    @load_moler_configuration_from_tl()
    def verify_ru_certificate_integrity(self, certificate_file_name, gnb_id=0, radio_unit_id=None,
                                        certificate_dir="/etc/ssl/certs/", du_id=0):
        """
        Verify that radio unit certificate file is present and verify it's integrity.
        :param du_id:                   DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param gnb_id:                  gNB id - related to Test Line configuration. Default: 0
        :param radio_unit_id:           radio unit id - related to Test Line configuration.
                                        If None certificate on each radio unit is checked.
        :param certificate_dir:         directory where certificate file is located. Default: /etc/ssl/certs/
        :param certificate_file_name:   name of certificate file. Default: NokiaModule.pem
        :return:                        None
        """
        if radio_unit_id is None:
            number_of_ru = tl_config.get_count_of_radios(bts_id=gnb_id, du_id=du_id, bts_type=self.bts_type)
            for ru_id in range(number_of_ru):
                self.verify_ru_certificate_integrity(gnb_id=gnb_id, radio_unit_id=ru_id,
                                                     certificate_dir=certificate_dir,
                                                     certificate_file_name=certificate_file_name, du_id=du_id)
            return

        ru = self.get_ru_device(bts_id=gnb_id, du_id=du_id, ru_id=radio_unit_id)
        self._verify_ru_certificate_file_present(radio_unit_device=ru, certificate_dir=certificate_dir,
                                                 certificate_file_name=certificate_file_name)
        openssl_cmd = ru.get_cmd(cmd_name='openssl_x509_text_in',
                                 cmd_params={'path': certificate_dir + certificate_file_name})
        try:
            openssl_cmd()
        except CommandFailure as e:
            raise CertificateVerificationError("Decoding certificate file on RU {} ended with error: {}".format(
                radio_unit_id, e))

    def _verify_ru_certificate_file_present(self, radio_unit_device, certificate_dir, certificate_file_name):
        """
        Verify that radio unit certificate file is present in given location.
        :param radio_unit_device:        radio unit moler device
        :param certificate_dir:          directory where certificate file is located
        :param certificate_file_name:    name of certificate file
        :return:                         None
        """
        cd_cmd = radio_unit_device.get_cmd(cmd_name='cd', cmd_params={'path': certificate_dir})
        ls_cmd = radio_unit_device.get_cmd(cmd_name='ls',
                                           cmd_params={'options': '-al | grep "{}"'.format(certificate_file_name)})
        cd_cmd()
        ls_cmd_output = ls_cmd()
        file_names = list(ls_cmd_output["files"].keys())
        if certificate_file_name in file_names:
            logging.info("Certificate file '{}' has been found".format(certificate_file_name))
        else:
            raise DataNotAvailable("Certificate file '{}' does not exist in path {}".format(certificate_file_name,
                                                                                            certificate_dir))

    @login_logout
    def verify_restart_occured_on_all_ru(self, bts_id=0, time=120, du_id=0):
        """
        Verifies if restart occured on all RUs in given time.
        :param bts_id:          BTS id - related to Test Line configuration.
        :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param time:            Time in seconds, that will be compared to uptime
        :return:                none
        """
        number_of_ru = tl_config.get_count_of_radios(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        for ru_id in range(number_of_ru):
            self.verify_ru_restart_occured(bts_id=bts_id, time=time, ru_id=ru_id, du_id=du_id)

    @load_moler_configuration_from_tl()
    def verify_ru_restart_occured(self, bts_id=0, time=120, ru_id=0, du_id=0):
        """
        Verifies if RU uptime is shorter that given time, indicating that Ru restart occurred.
        :param bts_id:          BTS id - related to Test Line configuration.
        :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param time:            Time in seconds, that will be compared to uptime
        :param ru_id:           Radio Unit id - related to Test Line configuration
        :return:                none
        """

        ru = self.get_ru_device(bts_id=bts_id, du_id=du_id, ru_id=ru_id)
        uptime_cmd = ru.get_cmd(cmd_name="uptime")
        uptime_result = uptime_cmd()['UPTIME_SECONDS']

        if uptime_result > int(time):
            raise UptimeTooLong("Expected uptime: < {}s, actual uptime: {}s".format(time, uptime_result))

        MolerTest.steps_end()
        return

    @load_moler_configuration_from_tl()
    def _get_container_id_gnb2ru(self, dev_name):
        """
        Get container id to connect to RU from GNB console.
        :param dev_name: Moler name of gnb.
        :return:         String with container id.
        """
        container_id = None
        containers = ("0x2018", "0x1018")
        try:
            dev = DeviceFactory.get_device(dev_name)
            dev.goto_state("FCT")
            cmd = dev.get_cmd(cmd_name="lxc_ls")
            ret = cmd()

            for current_container in containers:
                for container_row in ret['RESULT']:
                    if current_container in container_row:
                        logging.debug("Found Container id ='{}'".format(current_container))
                        container_id = current_container
                        return container_id
        except MolerException as me:
            logging.warning("Cannot get proper name of virtual machine because of: '{}'.".format(repr(me)))
        logging.info("Cannot find any container from: {}.".format(containers))
        return container_id

    @load_moler_configuration_from_tl()
    @MolerTest.raise_background_exceptions(check_steps_end=True)
    @login_logout
    def provoke_ru_supervision_failure(self, bts_id=0, du_id=0):
        """
        Provokes RU supervision failures by blocking communication, using iptables rules.
        :param bts_id:  BTS id - related to Test Line configuration.
        :param du_id:   DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:        none
        """
        gnb = DeviceFactory.get_device(name=self.ssh_alias.format(bts_id, du_id))

        container_id = self._get_container_id_gnb2ru(dev_name=gnb.name)
        gnb.change_fhnet_container_id(container_id=container_id)
        if container_id is not None:
            gnb.goto_state("FHNET")
        else:
            gnb.goto_state("FCT")

        add_iptables_rule_cmd_1 = gnb.get_cmd(cmd_name="iptables",
                                              cmd_params={'options': '-A INPUT -p udp --dport 13001 -j DROP'})
        add_iptables_rule_cmd_2 = gnb.get_cmd(cmd_name="iptables",
                                              cmd_params={'options': '-A OUTPUT -p udp --dport 13100 -j DROP'})

        add_iptables_rule_cmd_1()
        add_iptables_rule_cmd_2()

        MolerTest.steps_end()
        return

    @load_moler_configuration_from_tl()
    @MolerTest.raise_background_exceptions(check_steps_end=True)
    @login_logout
    def restore_ru_supervision(self, bts_id=0, du_id=0):
        """
        Restores RU supervision by removinf iptables rules.
        :param bts_id:  BTS id - related to Test Line configuration.
        :param du_id:   DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:        none
        """
        gnb = DeviceFactory.get_device(name=self.ssh_alias.format(bts_id, du_id))

        container_id = self._get_container_id_gnb2ru(dev_name=gnb.name)
        gnb.change_fhnet_container_id(container_id=container_id)
        if container_id:
            gnb.goto_state("FHNET")
        else:
            gnb.goto_state("FCT")

        remove_iptables_rule_cmd_1 = gnb.get_cmd(cmd_name="iptables",
                                                 cmd_params={'options': '-D INPUT -p udp --dport 13001 -j DROP'})
        remove_iptables_rule_cmd_2 = gnb.get_cmd(cmd_name="iptables",
                                                 cmd_params={'options': '-D OUTPUT -p udp --dport 13100 -j DROP'})

        remove_iptables_rule_cmd_1()
        remove_iptables_rule_cmd_2()

        MolerTest.steps_end()
        return

    @load_moler_configuration_from_tl()
    def get_ru_discard_rules_info(self, gnb_id=0, du_id=0, radio_unit_id=0, rate_limit=False, table="filter"):
        """
        Retrieve discard packet counter from RU
        :param gnb_id:          BTS id - related to Test Line configuration. Default: 0
        :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param radio_unit_id:   RU id - related to Test line configuration - gnbs.dus.rus[]
        :param rate_limit:      chain counter flag - set to True for DISCARD-RATE-LIMIT, False for DISCARD
        :param table:           table to get values from, filter or pre_filter
        :return:                int with counter value
        """
        if table == 'filter':
            table_type = 'table ip filter'
            nft_options = 'list ' + table_type
        elif table == 'pre_filter':
            table_type = 'table netdev pre_filter'
            nft_options = "list " + table_type
        else:
            raise ValueError("table: invalid type: should be: filter or pre_filter")
        ru = self.get_ru_device(bts_id=gnb_id, du_id=du_id, ru_id=radio_unit_id)
        nft_list_cmd = ru.get_cmd(cmd_name="nft", cmd_params={"options": nft_options})
        ret = self._run_cmd_with_sudo_su(ru_obj=ru, cmd=nft_list_cmd)
        if rate_limit:
            return ret[table_type]['chain DISCARD-RATE-LIMIT']['counter']['packets']
        elif rate_limit is False:
            return ret[table_type]['chain DISCARD']['counter']['packets']
        else:
            for line in ret['table ip filter']['chain OUTPUT']['LINES']:
                if line.lower().startswith('icmp'):
                    return line
            raise ValueError("NFT: OUTPUT rule for rate limiting ICMP traffic not found")

    @load_moler_configuration_from_tl()
    def _execute_amswissknife_on_radio_module(self, operation, panel_id, gnb_id=0, du_id=0, ru_id=0):
        """
        Execute amswissknife command on radio module to enable or disable beams, according to panel_id parameter:
        0 - main radio unit, 1 - first extension panel, 2 - second extension panel
        :param operation:   operation to perform, use 'enable' or 'disable'
        :param panel_id:    -a flag in amswissknife command, id of radio module
        :param gnb_id:      gNB id - related to Test Line configuration.
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param ru_id:       RU id - ID related to Test Line configuration.
        """
        command_options_dict = {
            'enable': ['-a {} -s runtime -n 0'.format(panel_id), '-a {} -s runtime -n 1'.format(panel_id)],
            'disable': ['-a {} -s disabled -n 0'.format(panel_id), '-a {} -s disabled -n 1'.format(panel_id)]
        }
        ru = self.get_ru_device(bts_id=gnb_id, du_id=du_id, ru_id=ru_id)
        try:
            for options in command_options_dict[operation]:
                am_swissknife_cmd = ru.get_cmd(cmd_name="amswissknife", cmd_params={'options': options})
                self._run_cmd_with_sudo_su(ru_obj=ru, cmd=am_swissknife_cmd)
        except KeyError:
            AmswissknifeOperationNotAvailable(operation)

    def enable_beams(self, panel_id=0, gnb_id=0, du_id=0, ru_id=0):
        """
        Enable beams on hardware pointed by panel_id parameter.
        :param panel_id:    -a flag in amswissknife command, id of radio module;
                            0 - main radio unit (default), 1 - first extension panel, 2 - second extension panel
        :param gnb_id:      gNB id - related to Test Line configuration.
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param ru_id:       RU id - ID related to Test Line configuration.
        """
        self._execute_amswissknife_on_radio_module('enable', panel_id=panel_id, gnb_id=gnb_id, du_id=du_id,
                                                   ru_id=ru_id)

    def disable_beams(self, panel_id=0, gnb_id=0, du_id=0, ru_id=0):
        """
        Disable beams on hardware pointed by panel_id parameter.
        :param panel_id:    -a flag in amswissknife command, id of radio module;
                            0 - main radio unit (default), 1 - first extension panel, 2 - second extension panel
        :param gnb_id:      gNB id - related to Test Line configuration.
        :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param ru_id:       RU id - ID related to Test Line configuration.
        """
        self._execute_amswissknife_on_radio_module('disable', panel_id=panel_id, gnb_id=gnb_id, du_id=du_id,
                                                   ru_id=ru_id)
